D.topics.forEach(t=>{if(mappedTopics.has(t.id))return;const phase=D.curriculumPhases.find(p=>p.id===phaseByDomain[t.domain]);if(phase){phase.topics.push(t.id);mappedTopics.add(t.id);}});

